// MsgServer is the server API for Msg service.
type MsgServer interface {
	// UpdateParams defines a (governance) operation for updating the module
	// parameters. The authority defaults to the x/gov module account.
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	// OpenCase accuses an address, and freezes it while the validators decide.
	OpenCase(context.Context, *MsgOpenCase) (*MsgOpenCaseResponse, error)
	// VoteCase records one validator's judgement.
	VoteCase(context.Context, *MsgVoteCase) (*MsgVoteCaseResponse, error)
	// WithdrawCase takes back a case before the vote ends, lifting its freeze.
	WithdrawCase(context.Context, *MsgWithdrawCase) (*MsgWithdrawCaseResponse, error)
	// Sweep collects whatever a passed seizure can now reach. Permissionless and
	// repeatable: funds that were staked arrive later, when unbonding matures,
	// and somebody has to be able to collect them without another vote.
	Sweep(context.Context, *MsgSweep) (*MsgSweepResponse, error)
	// EmergencyFreeze lets the founders' group stop an account in one block,
	// without waiting for a validator to open a case.
	EmergencyFreeze(context.Context, *MsgEmergencyFreeze) (*MsgEmergencyFreezeResponse, error)
	// EmergencyRelease lets them let it go again, just as fast.
	EmergencyRelease(context.Context, *MsgEmergencyRelease) (*MsgEmergencyReleaseResponse, error)
	// ReverseCase is governance overturning a passed case: the appeal. It lifts
	// the freeze and records the reversal, and it is deliberately a slower
	// instrument than the one that imposed the freeze, because it is the one used
	// when the chain got it wrong.
	ReverseCase(context.Context, *MsgReverseCase) (*MsgReverseCaseResponse, error)
}

